CREATE TABLE #cov_1
 DISTSTYLE ALL
AS
SELECT
CAST(ancestor_concept_id AS BIGINT) * 1000 + 210 AS covariate_id,
	row_id,
	1 AS covariate_value 
FROM
(
	SELECT DISTINCT ancestor_concept_id,
		cohort.row_id AS row_id
	FROM @extraction_cohort cohort
	INNER JOIN @cdm_database_schema.condition_era
		ON cohort.subject_id = condition_era.person_id
	INNER JOIN #groups
		ON condition_concept_id = descendant_concept_id
	WHERE condition_era_start_date <= DATEADD(DAY,CAST(0 as int),cohort.cohort_start_date)
AND 
condition_era_end_date 
>= DATEADD(DAY,CAST(-365 as int),cohort.cohort_start_date)
		AND condition_concept_id != 0
) temp
;
